const input = $json ?? {};
const body = input.body ?? {};

const defaults = {
  // A própria URL do LinkedIn já representa a busca.
  // Não filtramos novamente por keyword dentro do n8n.
  keywords: [],

  max_age_hours: 24,
  timezone: 'UTC',

  rss_feeds: [
    {
      url: 'YOUR_FETCHRSS_FEED_URL_1',

      source: 'FetchRSS',

      search_keyword: 'YOUR_SEARCH_KEYWORD_1',

      location: '',

      work_mode: ''
    }
  ]
};


function normalizeKeywords(value) {
  if (Array.isArray(value)) {
    return value
      .map(String)
      .map(v => v.trim())
      .filter(Boolean);
  }

  if (typeof value === 'string') {
    return value
      .split(',')
      .map(v => v.trim())
      .filter(Boolean);
  }

  return [];
}


const requestedKeywords =
  normalizeKeywords(body.keywords).length
    ? normalizeKeywords(body.keywords)
    : normalizeKeywords(defaults.keywords);


const requestedMaxAge =
  Number(
    body.max_age_hours ??
    defaults.max_age_hours
  );


return [{
  json: {
    keywords: requestedKeywords,

    max_age_hours:
      Number.isFinite(requestedMaxAge) &&
      requestedMaxAge > 0
        ? requestedMaxAge
        : 24,

    timezone: defaults.timezone,
    rss_feeds:
      defaults.rss_feeds
  }
}];

const cfg = $input.first().json;

const feeds = (cfg.rss_feeds || [])
  .map(feed => {
    // Compatibilidade com feed antigo salvo apenas como URL
    if (typeof feed === 'string') {
      const url = feed.trim();

      return {
        url,
        source: url.includes('rss.app')
          ? 'RSS.app'
          : 'FetchRSS',
        search_keyword: '',
        location: '',
        work_mode: ''
      };
    }

    const url = String(feed.url || '').trim();

    return {
      url,

      source:
        String(feed.source || '').trim() ||
        (
          url.includes('rss.app')
            ? 'RSS.app'
            : 'FetchRSS'
        ),

      search_keyword:
        String(
          feed.search_keyword ||
          feed.keyword ||
          ''
        ).trim(),

      location:
        String(feed.location || '').trim(),

      work_mode:
        String(feed.work_mode || '').trim()
    };
  })
  .filter(feed =>
    /^https?:\/\//i.test(feed.url) &&
    !feed.url.includes('PASTE_') && !feed.url.includes('YOUR_')
  );


if (!feeds.length) {
  throw new Error(
    'Nenhum RSS feed real foi configurado no Resolve Search Plan.'
  );
}


return feeds.map(feed => ({
  json: {
    feed_url: feed.url,

    source: feed.source,

    search_keyword: feed.search_keyword,

    default_location: feed.location,

    default_work_mode: feed.work_mode,

    keywords: cfg.keywords || [],

    timezone: cfg.timezone,
    max_age_hours: cfg.max_age_hours || 24
  }
}));

const ctx = $('Loop RSS Feeds').item.json;

const keywords = Array.isArray(ctx.keywords)
  ? ctx.keywords
  : [];


function clean(value) {
  if (value === null || value === undefined) {
    return '';
  }

  return String(value)
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/\s+/g, ' ')
    .trim();
}


function cleanUrl(raw) {
  if (!raw) return '';

  try {
    const decoded = String(raw)
      .replace(/&amp;/g, '&');

    const url = new URL(decoded);

    if (
      /linkedin\.com$/i.test(url.hostname) ||
      /\.linkedin\.com$/i.test(url.hostname)
    ) {
      return (
        `${url.protocol}//${url.hostname}${url.pathname}`
      ).replace(/\/$/, '');
    }

    url.hash = '';
    url.search = '';

    return url
      .toString()
      .replace(/\/$/, '');

  } catch {
    return String(raw)
      .replace(/&amp;/g, '&')
      .split('?')[0]
      .split('#')[0]
      .trim();
  }
}


function jobIdFromUrl(url) {
  const value = String(url || '');

  const match =
    value.match(
      /\/jobs\/view\/(?:[^/?#]*-)?(\d+)(?:[/?#]|$)/i
    ) ||
    value.match(
      /\/jobs\/view\/(\d+)/i
    );

  return match?.[1] || `url:${value}`;
}


function keywordMatch(text, keyword) {
  const haystack = String(text || '')
    .toLowerCase();

  const wanted = String(keyword || '')
    .toLowerCase()
    .trim();

  if (!wanted) {
    return false;
  }

  if (haystack.includes(wanted)) {
    return true;
  }

  const tokens = wanted
    .split(/\s+/)
    .filter(token => token.length >= 2);

  return (
    tokens.length > 0 &&
    tokens.every(token =>
      haystack.includes(token)
    )
  );
}


/*
  Retorna exatamente:

  DD/MM/YYYY HH:mm

  Sem segundos e sem vírgula.
*/
function formatBrazilDateTime(value) {
  const date =
    value instanceof Date
      ? value
      : new Date(value);

  if (Number.isNaN(date.getTime())) {
    return '';
  }

  const parts =
    new Intl.DateTimeFormat(
      'en-US',
      {
        timeZone: ctx.timezone || 'UTC',

        day: '2-digit',
        month: '2-digit',
        year: 'numeric',

        hour: '2-digit',
        minute: '2-digit',

        hour12: false
      }
    )
      .formatToParts(date)
      .reduce((acc, part) => {
        acc[part.type] = part.value;
        return acc;
      }, {});

  return (
    `${parts.day}/` +
    `${parts.month}/` +
    `${parts.year} ` +
    `${parts.hour}:` +
    `${parts.minute}`
  );
}


function detectLanguage(title) {
  const text = String(title || '')
    .toLowerCase();

  const portuguese =
    /\b(engenheiro|engenheira|engenharia|desenvolvedor|desenvolvedora|analista|especialista|inteligência|dados|automação|remoto|remota|estágio|estagiário|estagiária|sênior|pleno|júnior)\b/i;

  const english =
    /\b(engineer|developer|analyst|specialist|intelligence|automation|remote|software|machine learning|data)\b/i;

  if (portuguese.test(text)) {
    return 'Portuguese';
  }

  if (english.test(text)) {
    return 'English';
  }

  return '';
}


function detectTimeType(text) {
  const value = String(text || '')
    .toLowerCase();

  if (
    /\bpart[- ]?time\b|\bmeio período\b/i.test(value)
  ) {
    return 'Part-time';
  }

  if (
    /\bfull[- ]?time\b|\btempo integral\b/i.test(value)
  ) {
    return 'Full-time';
  }

  return '';
}


function detectJobType(text) {
  const value = String(text || '')
    .toLowerCase();

  const types = [];

  if (
    /\bcontract\b|\bcontractor\b|\bcontrato\b/i.test(value)
  ) {
    types.push('Contract');
  }

  if (
    /\binternship\b|\bestágio\b|\bestagiário\b|\bestagiária\b/i.test(value)
  ) {
    types.push('Internship');
  }

  if (
    /\bfreelance\b|\bfreelancer\b/i.test(value)
  ) {
    types.push('Freelance');
  }

  if (
    /\btemporary\b|\btemporário\b|\btemporária\b/i.test(value)
  ) {
    types.push('Temporary');
  }

  if (
    /\bpj\b|\bpessoa jurídica\b/i.test(value)
  ) {
    types.push('PJ');
  }

  if (
    /\bclt\b/i.test(value)
  ) {
    types.push('CLT');
  }

  if (
    /\blong[- ]?term\b|\blongo prazo\b/i.test(value)
  ) {
    types.push('Long-term');
  }

  return [...new Set(types)]
    .join(', ');
}


function detectExperience(title) {
  const value = String(title || '')
    .toLowerCase();

  if (
    /\blead\b|\blíder\b|\blider\b/i.test(value)
  ) {
    return 'Lead';
  }

  if (
    /\bsenior\b|\bsênior\b|\bsr\.?\b/i.test(value)
  ) {
    return 'Senior';
  }

  if (
    /\bspecialist\b|\bespecialista\b/i.test(value)
  ) {
    return 'Specialist';
  }

  if (
    /\bpleno\b|\bmid[- ]?level\b|\bmid\b/i.test(value)
  ) {
    return 'Mid';
  }

  if (
    /\bjunior\b|\bjúnior\b|\bjr\.?\b/i.test(value)
  ) {
    return 'Junior';
  }

  if (
    /\bintern\b|\binternship\b|\bestagi[aá]ri[oa]\b/i.test(value)
  ) {
    return 'Intern';
  }

  return '';
}


/*
  No FetchRSS configuramos o Summary
  para trazer Location.

  Exemplo:

  Brazil
  (Feed generated with FetchRSS)
*/
function extractLocation(item) {
  const raw =
    item.contentSnippet ??
    item.description ??
    item.summary ??
    item.content ??
    '';

  return clean(raw)
    .replace(
      /\(?\s*Feed generated with FetchRSS\s*\)?/gi,
      ''
    )
    .trim();
}


const jobs = [];


for (const input of $input.all()) {
  const item = input.json || {};


  const rawUrl =
    item.link ||
    item.origLink ||
    item.guid ||
    item.url ||
    '';


  const url =
    cleanUrl(rawUrl);


  // Aceita somente vagas do LinkedIn.
  if (
    !/^https?:\/\/(?:[a-z0-9-]+\.)?linkedin\.com\/jobs\//i.test(url)
  ) {
    continue;
  }


  const published =
    item.isoDate ??
    item.pubDate ??
    item.published ??
    item.updated ??
    '';


  const publishedMs =
    Date.parse(published);


  if (
    Number.isNaN(publishedMs)
  ) {
    continue;
  }


  // Apply the reusable freshness setting independently of the source feed.
  const ageHours = (Date.now() - publishedMs) / 3600000;
  if (ageHours > Number(ctx.max_age_hours || 24) || ageHours < -1) continue;


  const title =
    clean(item.title) ||
    'Not specified';


  const companyName =
    clean(
      item.creator ??
      item['dc:creator'] ??
      item.author ??
      item.company ??
      ''
    );


  const extractedLocation =
    extractLocation(item);


  /*
    Location representa localização geográfica.

    default_location pode ser usado futuramente
    caso um feed tenha uma localização fixa.

    Atualmente o FetchRSS já entrega essa informação
    no Summary.
  */
  const location =
    clean(ctx.default_location) ||
    extractedLocation;


  /*
    Work Mode vem da configuração do feed.

    Neste FetchRSS atual:
    Remote
  */
  const workMode =
    [
      'Remote',
      'Hybrid',
      'On-site'
    ].includes(
      String(
        ctx.default_work_mode || ''
      ).trim()
    )
      ? String(
          ctx.default_work_mode
        ).trim()
      : '';


  /*
    Texto auxiliar apenas para detectar
    campos determinísticos.

    Não usamos como Description porque
    o FetchRSS atual não fornece a descrição
    completa da vaga.
  */
  const sourceText =
    [
      title,
      companyName,
      extractedLocation
    ]
      .filter(Boolean)
      .join(' ');


  const matchedKeyword =
    keywords.find(keyword =>
      keywordMatch(
        sourceText,
        keyword
      )
    );


  /*
    Atualmente keywords = [].

    Cada feed já representa uma busca
    específica do LinkedIn.
  */
  if (
    keywords.length &&
    !matchedKeyword
  ) {
    continue;
  }


  const scrapedNow =
    new Date();


  jobs.push({

    // A - Job ID
    job_id:
      jobIdFromUrl(url),

    // B - Status
    status:
      'To do',

    // C - Date Scraped
    date_scraped:
      formatBrazilDateTime(
        scrapedNow
      ),

    // D - Source
    source:
      ctx.source || 'FetchRSS',

    // E - Search Keyword
    search_keyword:
      ctx.search_keyword || '',

    // F - Date Posted
    date_posted:
      formatBrazilDateTime(
        new Date(publishedMs)
      ),

    // G - Title
    title,

    // H - Work Mode
    work_mode:
      workMode,

    // I - URL
    url,

    // J - Company Name
    company_name:
      companyName,

    // K - Location
    location,

    // L - Description
    description:
      '',

    // M - Language
    language:
      detectLanguage(title),

    // N - Payment
    payment:
      '',

    // O - Time Type
    time_type:
      detectTimeType(sourceText),

    // P - Job Type
    job_type:
      detectJobType(sourceText),

    // Q - Experience
    experience:
      detectExperience(title),

    // R - Salary
    salary:
      '',

    // S - Match
    match:
      '',

    // T - Qualified
    qualified:
      '',

    // U - Cover Letter
    cover_letter:
      '',

    // V - Notes
    notes:
      '',

    // W - Interview At
    interview_at:
      '',

    // X - Invite Meet
    invite_meet:
      '',

    // Y - Attended
    attended:
      false,


    // Campos internos

    posted_at:
      new Date(
        publishedMs
      ).toISOString(),

    scraped_at:
      scrapedNow.toISOString(),

    _feed_url:
      ctx.feed_url
  });
}


return [{
  json: {
    feed_url:
      ctx.feed_url,

    source:
      ctx.source || 'FetchRSS',

    search_keyword:
      ctx.search_keyword || '',

    jobs
  }
}];

const feedResults = $input.all().map(i => i.json || {});
const allJobs = [];

for (const result of feedResults) {
  const jobs = Array.isArray(result.jobs) ? result.jobs : [];
  allJobs.push(...jobs);
}

return [{
  json: {
    jobs: allJobs,
    rss_feed_count: feedResults.length,
    raw_job_count: allJobs.length
  }
}];

const jobs = Array.isArray($json.jobs)
  ? $json.jobs
  : [];

const seen = new Map();


function completeness(job) {
  const fields = [
    'title',
    'work_mode',
    'company_name',
    'location',
    'description',
    'language',
    'payment',
    'time_type',
    'job_type',
    'experience',
    'salary'
  ];

  return fields.reduce((score, field) => {
    const value = String(
      job[field] || ''
    ).trim();

    return score + (value ? 1 : 0);
  }, 0);
}


for (const job of jobs) {
  if (!job) {
    continue;
  }

  const key = String(
    job.job_id ||
    job.url ||
    ''
  ).trim();

  if (!key) {
    continue;
  }


  // Primeira ocorrência da vaga.
  if (!seen.has(key)) {
    seen.set(key, job);
    continue;
  }


  const current =
    seen.get(key);


  /*
    Se a mesma vaga aparecer em mais de um feed,
    mantemos a versão que possui mais campos
    preenchidos.
  */
  if (
    completeness(job) >
    completeness(current)
  ) {
    seen.set(key, job);
  }
}


return [...seen.values()]
  .map(job => ({
    json: job
  }));

function nodeItems(name) {
  try {
    return $(name).all();
  } catch {
    return [];
  }
}

const aggregate =
  nodeItems('Aggregate RSS Results')[0]?.json || {};

const uniqueJobs =
  nodeItems('Deduplicate + Split Jobs').length;

return [{
  json: {
    status: 'completed',
    source: 'rss',
    rss_feed_count:
      Number(aggregate.rss_feed_count || 0),
    raw_job_count:
      Number(aggregate.raw_job_count || 0),
    unique_job_count:
      uniqueJobs,
    message:
      'RSS search completed.'
  }
}];
